# Compute per-layer readout vectors for Wait-like tokens and </think>
import numpy as np, torch, json, pickle
E = load_original("model.language_model.embed_tokens.weight").float()
gamma = load_original("model.language_model.norm.weight").float()
rng = (1.0 + gamma)
print("E", E.shape, "gamma", gamma.shape)
read = {}
for tok_id, name in [(13428,"wait"),(248069,"think_end"),(628,"final_answer_tok?")]:
    read[name] = (E[tok_id] * rng)  # [hidden]
w = {}
for L in range(24):
    d = load_original(f"model.language_model.layers.{L}.mlp.down_proj.weight").float()  # [hidden, inter]
    w[L] = {name: d.T @ vec for name, vec in read.items()}
print("done")
np.save("/work/read_vectors.npy", np.stack([read["wait"].numpy(), read["think_end"].numpy()]))

